import os, json, sys
sys.path.append('storage/shared/atlas/tools')
import ci_validate

def exists_all(paths):
    return all(os.path.exists(p) for p in paths)

def load_index(path):
    if os.path.exists(path):
        try:
            with open(path, 'r', encoding='utf-8') as f:
                return json.load(f)
        except Exception:
            pass
    return {"entries": [], "updated": None}

def norm_entries(d):
    out = []
    for e in d.get("entries", []):
        if isinstance(e, dict) and "entry_path" in e:
            out.append({"entry_path": e["entry_path"]})
        elif isinstance(e, dict) and "path" in e:
            out.append({"entry_path": e["path"]})
        elif isinstance(e, str):
            out.append({"entry_path": e})
    return out

def save_index(path, entries):
    data = {"entries": entries, "updated": __import__('datetime').datetime.utcnow().isoformat() + "Z"}
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w', encoding='utf-8') as f:
        json.dump(data, f, ensure_ascii=False, indent=2)

# Targets
z_dir = 'storage/shared/atlas/edges/zephyr/variance_renewal'
z_entry = f'{z_dir}/entry.json'
z_artifacts = [f'{z_dir}/hinge_metrics_post.csv', f'{z_dir}/hinge_summary_post.txt', f'{z_dir}/panel_post.png']

l_dir = 'storage/shared/atlas/edges/logos/verification_entropy'
l_entry = f'{l_dir}/entry.json'
l_artifacts = [f'{l_dir}/verification_metrics.csv', f'{l_dir}/verification_summary.txt', f'{l_dir}/verification_panel.png']

idx_path = 'storage/shared/atlas/edges/index.json'
idx = load_index(idx_path)
ents = norm_entries(idx)
before = set(e["entry_path"] for e in ents)

updates = []
# Zephyr: add only if artifacts exist
if os.path.exists(z_entry) and exists_all(z_artifacts) and z_entry not in before:
    ents.append({"entry_path": z_entry})
    updates.append({"added": z_entry})
# Logos: add only if artifacts exist
if os.path.exists(l_entry) and exists_all(l_artifacts) and l_entry not in before:
    ents.append({"entry_path": l_entry})
    updates.append({"added": l_entry})

# Sort deterministically
ents = sorted(ents, key=lambda e: e["entry_path"])
if updates:
    save_index(idx_path, ents)

# Run CI regardless (to confirm green)
out = ci_validate.run()
print(json.dumps({
    "status": "ok",
    "index_updates": updates,
    "entries_before": len(before),
    "entries_after": len(ents),
    "ci_entries_found": out.get("entries_found"),
    "ci_ok": out.get("ok"),
    "ci_with_errors": out.get("with_errors"),
    "report_json": "storage/shared/atlas/edges/ci_validation_report.json",
    "report_txt": "storage/shared/atlas/edges/ci_validation_report.txt"
}))
